"""Contact data generator: the workflow as a program. Generated by Agent Workflow Studio from the published
release; export again rather than edit (the steps it calls are in core/, unchanged from the studio)."""

from pathlib import Path

from .core import bench, runner  # noqa: F401

HERE = Path(__file__).parent
TITLE, VERSION = 'Contact data generator', '1.0.0'
PURPOSE = ('Generate CRM-shaped contacts with realistic dirt and their answer key, to try or measure contact '
 'matching.')
# The workflow's App inputs: name -> [default, type, description, choices].
INPUTS = {'profile': ['company_hard',
             'COMBO',
             'How dirty. Lifelike and company profiles take names from public lists (downloaded '
             'once). All contacts are synthetic.',
             ['base',
              'dirty',
              'sparse',
              'lookalike',
              'wild',
              'hard',
              'lifelike',
              'company',
              'company_hard',
              'lifelike_hard']],
 'contacts': [10000, 'INT', 'About how many contacts to generate.', None],
 'seed': [7, 'INT', 'The same seed gives the same data.', None]}
OUTPUTS = ['folder', 'answer_key']
FOLDERS = []  # inputs that name a data folder
EXAMPLES = [{'id': 'E1',
  'given': {'profile': 'hard', 'contacts': 300, 'seed': 3},
  'expect': {'folder': 'contacts_benchmark/hard_300_3'},
  'note': 'A small hard set (no downloads needed).'}]


def run(out, labels=None, **given):
    """Run the workflow; `given` overrides any input. Returns the runtime (checks, outputs, lines)."""
    values = {k: (given[k] if given.get(k) is not None else d) for k, (d, *_) in INPUTS.items()}
    input_dir = Path(out)
    for name in FOLDERS:
        folder = Path(str(values[name]).replace("@examples", str(HERE / "examples"), 1)).resolve()
        if not folder.is_dir():
            raise SystemExit(f"No folder {folder} for --{name.replace('_', '-')}.")
        input_dir, values[name] = folder.parent, folder.name
    rt = runner.Runtime(Path(out), input_dir, labels)
    n4_1 = bench.synthetic_contacts(rt.ctx('synthetic_contacts'), profile=values['profile'], contacts=values['contacts'], seed=values['seed'])  # Synthetic contacts
    n2 = runner.api_output(rt.ctx('api_output'), name='folder', value=n4_1[0])  # Output · folder
    n3 = runner.api_output(rt.ctx('api_output'), name='answer_key', value=n4_1[1])  # Output · answer_key
    n4_5 = runner.check(rt.ctx('check'), kind='contains', expect='contacts_benchmark', says='The data folder is written (with its answer key beside it).', value=n4_1[0])  # Check · folder
    return rt
